// Room-find index — record JAH-GGNS-BTTRACKER-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"range_m": 60, "battery_years": 1, "price_usd": 25};
var value = (m.range_m*m.battery_years/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GGNS-BTTRACKER-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GGNS-BTTRACKER-000001|' + value.toFixed(2) + ' find index');

